// ✅ SECURE: Scoped to the authenticated user's organization
export async function deleteUserInvoice(invoiceId: string, orgId: string) {
  return await prisma.invoice.delete({
    where: {
      id: invoiceId,
      organizationId: orgId, // Must match tenant constraint!
    }
  });
}

import { Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';

async function searchUsersByName(nameInput: string) {
  // ✅ SAFE: Tagged template creates parameterized query ($1)
  return await prisma.$queryRaw<User[]>`
    SELECT id, name, email 
    FROM "users" 
    WHERE name ILIKE ${'%' + nameInput + '%'}
  `;
}
